interface HeaderProps {
  currentView: View;
  onChangeView: (view: View) => void;
  language: Language;
  onToggleLanguage: () => void;
}

export const Header: React.FC<HeaderProps> = ({ currentView, onChangeView, language, onToggleLanguage }) => {
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [imgError, setImgError] = useState(false);

  const getNavItems = (lang: Language): NavItem[] => [
    { label: lang === 'fr' ? 'Accueil' : 'Home', view: View.HOME },
    { label: lang === 'fr' ? "L'Entreprise" : 'About Us', view: View.ABOUT },
    { label: lang === 'fr' ? 'Prestations' : 'Services', view: View.SERVICES },
    { label: lang === 'fr' ? 'Activités' : 'Activities', view: View.ACTIVITIES },
    { label: lang === 'fr' ? 'Stratégies' : 'Strategy', view: View.STRATEGY },
    { label: lang === 'fr' ? 'Contact' : 'Contact', view: View.CONTACT },
  ];

  const NAV_ITEMS = getNavItems(language);

  const handleNavClick = (view: View) => {
    onChangeView(view);
    setIsMobileMenuOpen(false);
  };

  return (
    <header className="sticky top-0 z-50 bg-white/90 backdrop-blur-md shadow-sm border-b border-emerald-100">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex justify-between items-center h-40">
          {/* Logo */}
          <div 
            className="flex items-center cursor-pointer group" 
            onClick={() => handleNavClick(View.HOME)}
          >
            {/* Logo Image */}
            <div className="relative h-32 w-32 mr-6 transition-transform duration-300 group-hover:scale-105 flex-shrink-0">
              {!imgError ? (
                <img 
                  src="https://drive.google.com/thumbnail?id=1fuy_xQJH5LZGyoPu_0Hc7-pDsrnIPuF6&sz=w400" 
                  alt="Logo R.I.C.E" 
                  className="h-full w-full object-contain drop-shadow-sm"
                  onError={() => setImgError(true)}
                />
              ) : (
                <div className="h-full w-full bg-emerald-100 rounded-full flex items-center justify-center">
                  <Leaf className="h-16 w-16 text-emerald-600" />
                </div>
              )}
            </div>

            <div className="flex flex-col justify-center">
              <span className="text-7xl font-bold text-emerald-900 tracking-tight leading-none">R.I.C.E</span>
              <span className="text-xl leading-tight text-emerald-600 font-bold tracking-wider hidden sm:block mt-2">
                {language === 'fr' ? 'INGÉNIERIE ENVIRONNEMENTALE' : 'ENVIRONMENTAL ENGINEERING'}
              </span>
            </div>
          </div>

          {/* Desktop Navigation */}
          <nav className="hidden md:flex space-x-8 items-center">
            {NAV_ITEMS.map((item) => (
              <button
                key={item.view}
                onClick={() => handleNavClick(item.view)}
                className={`text-sm font-medium transition-colors duration-200 ${
                  currentView === item.view
                    ? 'text-emerald-700 border-b-2 border-emerald-600'
                    : 'text-gray-500 hover:text-emerald-600'
                }`}
              >
                {item.label}
              </button>
            ))}
            <button 
              onClick={onToggleLanguage}
              className="flex items-center text-gray-500 hover:text-emerald-600 ml-4 px-3 py-1 border border-gray-200 rounded-full hover:border-emerald-500 transition-all"
            >
               <Globe className="h-4 w-4 mr-2" />
               <span className="text-xs font-bold uppercase">{language}</span>
            </button>
          </nav>

          {/* Mobile Menu Button */}
          <div className="md:hidden flex items-center space-x-4">
            <button 
              onClick={onToggleLanguage}
              className="flex items-center text-gray-500 hover:text-emerald-600 px-2 py-1 border border-gray-200 rounded-full"
            >
               <span className="text-xs font-bold uppercase">{language}</span>
            </button>
            <button
              onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
              className="text-gray-500 hover:text-emerald-700 focus:outline-none"
            >
              {isMobileMenuOpen ? <X className="h-6 w-6" /> : <Menu className="h-6 w-6" />}
            </button>
          </div>
        </div>
      </div>

      {/* Mobile Menu */}
      {isMobileMenuOpen && (
        <div className="md:hidden bg-white border-t border-gray-100 absolute w-full shadow-lg">
          <div className="px-2 pt-2 pb-3 space-y-1 sm:px-3">
            {NAV_ITEMS.map((item) => (
              <button
                key={item.view}
                onClick={() => handleNavClick(item.view)}
                className={`block px-3 py-2 rounded-md text-base font-medium w-full text-left ${
                  currentView === item.view
                    ? 'text-emerald-700 bg-emerald-50'
                    : 'text-gray-600 hover:text-emerald-600 hover:bg-gray-50'
                }`}
              >
                {item.label}
              </button>
            ))}
          </div>
        </div>
      )}
    </header>
  );
};

