import React, { useState, useEffect } from 'react';
import { Header } from './components/Header';
import { Footer } from './components/Footer';
import { Assistant } from './components/Assistant';
import { View, Language } from './types';

// Views
import { HomeView } from './components/views/HomeView';
import { AboutView } from './components/views/AboutView';
import { ServicesView } from './components/views/ServicesView';
import { ActivitiesView } from './components/views/ActivitiesView';
import { StrategyView } from './components/views/StrategyView';
import { ContactView } from './components/views/ContactView';
import { LegalView } from './components/views/LegalView';
import { PrivacyView } from './components/views/PrivacyView';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<View>(View.HOME);
  const [language, setLanguage] = useState<Language>('fr');

  // Scroll to top when view changes
  useEffect(() => {
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }, [currentView]);

  const renderView = () => {
    switch (currentView) {
      case View.HOME:
        return <HomeView onChangeView={setCurrentView} language={language} />;
      case View.ABOUT:
        return <AboutView language={language} />;
      case View.SERVICES:
        return <ServicesView language={language} />;
      case View.ACTIVITIES:
        return <ActivitiesView language={language} />;
      case View.STRATEGY:
        return <StrategyView language={language} />;
      case View.CONTACT:
        return <ContactView language={language} />;
      case View.LEGAL:
        return <LegalView language={language} />;
      case View.PRIVACY:
        return <PrivacyView language={language} />;
      default:
        return <HomeView onChangeView={setCurrentView} language={language} />;
    }
  };

  return (
    <div className="font-sans text-slate-700 antialiased min-h-screen flex flex-col bg-slate-50">
      <Header 
        currentView={currentView} 
        onChangeView={setCurrentView} 
        language={language}
        onToggleLanguage={() => setLanguage(l => l === 'fr' ? 'en' : 'fr')}
      />

      <main className="flex-grow">
        {renderView()}
      </main>

      <Footer onLinkClick={setCurrentView} language={language} />

      {/* Smart Assistant powered by Gemini */}
      <Assistant language={language} />
    </div>
  );
};

export default App;

